function packQuestion(type, spec, passage, vocabulary) {
  const hints = {
    detail:['Scan for the exact detail asked in the question.', 'Read the sentence around the matching clue.', 'Choose the option that the passage directly supports.'],
    'main idea':['Think about the whole passage, not one interesting detail.', 'Notice the repeated topic and the writer’s final point.', 'State the central message in your own words before choosing.'],
    inference:['Find the clue that supports a conclusion.', 'Separate what the text suggests from what you merely imagine.', 'Choose the conclusion that needs the fewest assumptions.'],
    vocabulary:['Read the word in its sentence.', 'Use the actions, examples or contrast nearby.', 'Replace the word with an option and check whether the sentence still makes sense.']
  }[type] || ['Return to the passage.', 'Use the nearby evidence.', 'Choose the best-supported option.'];
  return {question:spec.question, options:spec.options, answer:spec.answer, type, evidence:spec.evidence || passage, explanation:spec.explanation, hints};
}

function makePackReading(item) {
  const vocabulary = [{word:item.word, indonesian:item.indonesian, meaning:item.meaning}];
  const questions = [
    packQuestion('detail', item.detail, item.passage, vocabulary),
    packQuestion('main idea', item.main, item.passage, vocabulary),
    packQuestion('inference', item.inference, item.passage, vocabulary),
    packQuestion('vocabulary', {question:`In the passage, what does “${item.word}” most nearly mean?`, options:item.vocabOptions, answer:item.vocabAnswer || 0, evidence:item.vocabEvidence || item.passage, explanation:`Here, “${item.word}” means ${item.meaning}.`}, item.passage, vocabulary)
  ];
  const rotation = item.id.split('').reduce((sum, char) => sum + char.charCodeAt(0), 0) % 4;
  questions.forEach((question, index) => {
    const shift = (rotation + index) % question.options.length;
    question.options = question.options.map((_, optionIndex) => question.options[(optionIndex - shift + question.options.length) % question.options.length]);
    question.answer = (question.answer + shift) % question.options.length;
  });
  return {id:item.id, title:item.title, level:item.level, category:item.category, passage:item.passage, questions, vocabulary};
}

const READING_PASTURE_PACK = [
  {id:'pack-l1-01',title:'The Borrowed Raincoat',level:1,category:'Everyday',passage:'The sky turns gray when Rafi leaves school. His friend Mina lends him a yellow raincoat from the classroom cupboard. Rafi thanks her and walks home slowly because the pavement is wet. At the gate, he hangs the raincoat on a hook so Mina can use it tomorrow.',word:'lend',indonesian:'meminjamkan',meaning:'give something to someone for a short time',detail:{question:'Why does Rafi walk home slowly?',options:['The pavement is wet','He is looking for a bus','He has lost his shoes','He wants to buy a raincoat'],answer:0,evidence:'Rafi thanks her and walks home slowly because the pavement is wet.',explanation:'The passage gives the wet pavement as the reason.'},main:{question:'What is the passage mainly about?',options:['A friend helps another friend stay dry','A student buys a new uniform','A class cleans the playground','A family prepares dinner'],answer:0,evidence:'Mina lends him a yellow raincoat... Rafi hangs the raincoat on a hook so Mina can use it tomorrow.',explanation:'The central event is Mina helping Rafi and Rafi returning the item responsibly.'},inference:{question:'What can readers infer about Rafi?',options:['He tries to take care of borrowed things','He dislikes walking home','He never talks to Mina','He wants to keep the raincoat'],answer:0,evidence:'At the gate, he hangs the raincoat on a hook so Mina can use it tomorrow.',explanation:'Returning the raincoat carefully suggests responsibility.'},vocabOptions:['give something to someone for a short time','make something wet','hide an object','buy something cheaply'],vocabAnswer:0},
  {id:'pack-l1-02',title:'A Place for the Seeds',level:1,category:'Nature',passage:'Naya finds three small seed packets in a drawer. She writes bean, corn and spinach on a paper label. Then she puts the packets in a cool box beside the window. Her father says the labels will help the family remember what to plant in the garden.',word:'label',indonesian:'label atau tanda nama',meaning:'a piece of paper that identifies something',detail:{question:'Where does Naya put the seed packets?',options:['In a cool box beside the window','Under the garden soil','Inside her school bag','On the kitchen table'],answer:0,evidence:'Then she puts the packets in a cool box beside the window.',explanation:'The location appears directly in the third sentence.'},main:{question:'What is the main purpose of Naya’s action?',options:['To identify and organise the seeds','To cook vegetables for dinner','To give seeds to her teacher','To measure the window'],answer:0,evidence:'She writes bean, corn and spinach on a paper label.',explanation:'The labels organise the packets and show what each contains.'},inference:{question:'Why might the cool box be useful?',options:['It keeps the packets together in one place','It makes the window larger','It waters the garden automatically','It turns seeds into food'],answer:0,evidence:'Then she puts the packets in a cool box beside the window.',explanation:'The text does not state every reason, but the box clearly stores the packets together.'},vocabOptions:['a piece of paper that identifies something','a tool for digging soil','a small insect','a type of vegetable'],vocabAnswer:0},
  {id:'pack-l1-03',title:'The Library Bell',level:1,category:'School',passage:'Every afternoon, a small bell rings in the library. The sound tells visitors that the reading room will close in ten minutes. Tio checks the shelves and returns one book to its place. He leaves after the librarian thanks him for helping keep the room tidy.',word:'close',indonesian:'tutup',meaning:'stop allowing people to enter or use a place',detail:{question:'What does the bell tell visitors?',options:['The room will close in ten minutes','A lesson will begin tomorrow','A new book has arrived','The lights are broken'],answer:0,evidence:'The sound tells visitors that the reading room will close in ten minutes.',explanation:'The bell is a warning about closing time.'},main:{question:'What is the passage mainly about?',options:['A library closing routine','A noisy classroom experiment','A lost library card','A new school subject'],answer:0,evidence:'Every afternoon, a small bell rings in the library... Tio leaves after helping keep the room tidy.',explanation:'The passage describes the closing routine and Tio’s small act of help.'},inference:{question:'What can readers infer about Tio?',options:['He notices where books belong','He avoids the librarian','He is afraid of bells','He wants the library to close early'],answer:0,evidence:'Tio checks the shelves and returns one book to its place.',explanation:'Returning the book correctly shows care for the library.'},vocabOptions:['stop allowing people to enter or use a place','make a loud sound','open a book quickly','carry a shelf'],vocabAnswer:0},
  {id:'pack-l1-04',title:'The Lunch Garden',level:1,category:'Food',passage:'At school, Bima sits near a garden during lunch. He notices that the soil around one plant is dry. After eating, he fills a small watering can and gives the plant some water. The teacher explains that a little water every morning is better than too much water once a week.',word:'dry',indonesian:'kering',meaning:'without enough water or moisture',detail:{question:'What does Bima do after eating?',options:['He waters a plant','He leaves the school','He picks all the flowers','He fills a lunch box'],answer:0,evidence:'After eating, he fills a small watering can and gives the plant some water.',explanation:'Bima waters the dry plant.'},main:{question:'What lesson does the teacher explain?',options:['Regular small care can help a plant','Plants should stay inside a cupboard','Lunch should be eaten in the garden','A watering can is a lunch tool'],answer:0,evidence:'A little water every morning is better than too much water once a week.',explanation:'The teacher emphasises a regular care routine.'},inference:{question:'Why does Bima notice the plant?',options:['He pays attention to the garden around him','He wants to sell the plant','He is searching for his lunch','He dislikes all outdoor activities'],answer:0,evidence:'He notices that the soil around one plant is dry.',explanation:'Observing the soil shows attention to the garden.'},vocabOptions:['without enough water or moisture','full of seeds','very noisy','ready to eat'],vocabAnswer:0},
  {id:'pack-l1-05',title:'The Quiet Bus Stop',level:1,category:'Travel',passage:'Sela arrives at the bus stop before seven. A sign says, “Please stand behind the white line.” She reads the sign and waits with her bag behind the line. When the bus arrives, she lets an older passenger enter first.',word:'behind',indonesian:'di belakang',meaning:'at the back or on the far side of something',detail:{question:'Where does Sela wait?',options:['Behind the white line','Inside the bus','In front of the driver','Across the road'],answer:0,evidence:'She reads the sign and waits with her bag behind the line.',explanation:'The passage directly states where she waits.'},main:{question:'What is the passage mainly about?',options:['A safe and polite bus-stop routine','A long journey across the country','A broken bus sign','A school sports day'],answer:0,evidence:'Please stand behind the white line... she lets an older passenger enter first.',explanation:'The text highlights safety and courtesy.'},inference:{question:'Why does Sela let the older passenger enter first?',options:['She is showing courtesy','She has forgotten her bag','She wants to miss the bus','She cannot read the sign'],answer:0,evidence:'When the bus arrives, she lets an older passenger enter first.',explanation:'Letting the passenger go first is a polite action.'},vocabOptions:['at the back or on the far side of something','in the middle of a road','above a building','inside a bag'],vocabAnswer:0},
  {id:'pack-l1-06',title:'A Small Repair',level:1,category:'Home',passage:'The handle on Danu’s cup becomes loose. He tells his aunt instead of throwing the cup away. Together, they tighten the small screw with a screwdriver. Danu washes the cup and uses it again for his morning milk.',word:'loose',indonesian:'longgar',meaning:'not firmly fixed in place',detail:{question:'What becomes loose?',options:['The handle on Danu’s cup','The kitchen window','A school uniform','A garden gate'],answer:0,evidence:'The handle on Danu’s cup becomes loose.',explanation:'The first sentence names the loose part.'},main:{question:'What is the central idea of the passage?',options:['A simple repair can give an item more use','Every cup should be thrown away','Danu learns to cook milk','A screwdriver is a type of cup'],answer:0,evidence:'Together, they tighten the small screw... Danu uses it again.',explanation:'Repairing the handle allows the cup to be reused.'},inference:{question:'What value does Danu’s action show?',options:['He tries to avoid unnecessary waste','He dislikes drinking milk','He wants a new screwdriver','He never asks adults for help'],answer:0,evidence:'He tells his aunt instead of throwing the cup away.',explanation:'Choosing repair over disposal suggests a waste-conscious attitude.'},vocabOptions:['not firmly fixed in place','very clean and shiny','filled with liquid','too heavy to carry'],vocabAnswer:0},
  {id:'pack-l1-07',title:'The Market List',level:1,category:'Everyday',passage:'Before going to the market, Ika writes three items on a list: rice, bananas and soap. At the first stall, she buys the rice. At the second stall, she finds bananas but no soap. She circles soap on the list and asks her mother to look for it at another stall.',word:'item',indonesian:'barang atau benda',meaning:'one thing on a list or in a group',detail:{question:'Which item is not available at the second stall?',options:['Soap','Rice','Bananas','A market list'],answer:0,evidence:'She finds bananas but no soap.',explanation:'The sentence directly says that soap is missing.'},main:{question:'Why does Ika write a list?',options:['To remember what to buy','To practise drawing stalls','To count the market doors','To choose a bus route'],answer:0,evidence:'Ika writes three items on a list: rice, bananas and soap.',explanation:'A shopping list helps her remember the planned purchases.'},inference:{question:'What will Ika probably do next?',options:['Look for soap at another stall','Return the bananas to the first stall','Throw away the list','Go home without speaking to her mother'],answer:0,evidence:'She asks her mother to look for it at another stall.',explanation:'Her request clearly points to the next action.'},vocabOptions:['one thing on a list or in a group','a person who sells food','a place for parking','a written thank-you note'],vocabAnswer:0},
  {id:'pack-l1-08',title:'A Cloudy Picnic',level:1,category:'Leisure',passage:'The class plans a picnic beside the lake. In the morning, dark clouds cover the sky, so the teacher moves the picnic to the school hall. The students place their food on long tables and play a word game. They still enjoy the day because they can talk and laugh together.',word:'move',indonesian:'memindahkan',meaning:'change the position or place of something',detail:{question:'Where does the teacher move the picnic?',options:['To the school hall','To the lake shore','To a market stall','To a bus stop'],answer:0,evidence:'The teacher moves the picnic to the school hall.',explanation:'The destination is stated directly.'},main:{question:'What is the passage mainly about?',options:['A class adapts its picnic plan because of weather','A group learns to swim in a lake','A teacher buys food for a class','A word game that is difficult to finish'],answer:0,evidence:'Dark clouds cover the sky, so the teacher moves the picnic to the school hall.',explanation:'The change of plan is the main event.'},inference:{question:'Why do the students still enjoy the day?',options:['They can share food and play together','The clouds disappear immediately','They receive new school bags','They go swimming in the lake'],answer:0,evidence:'They still enjoy the day because they can talk and laugh together.',explanation:'The text names talking and laughing as reasons.'},vocabOptions:['change the position or place of something','watch clouds from a window','make food taste sweet','write a plan quickly'],vocabAnswer:0},
  {id:'pack-l1-09',title:'The Blue Door',level:1,category:'Community',passage:'A blue door stands at the end of the community garden. Behind it is a small tool room. On Saturday, Fajar takes a broom from the room and sweeps the path. He returns the broom before going home and closes the door carefully.',word:'return',indonesian:'mengembalikan',meaning:'take or bring something back',detail:{question:'What does Fajar take from the tool room?',options:['A broom','A blue door','A flower pot','A path sign'],answer:0,evidence:'Fajar takes a broom from the room and sweeps the path.',explanation:'The broom is the tool he takes.'},main:{question:'What is the passage mainly about?',options:['A child uses and returns a community tool','A gardener paints a blue door','A path is closed for a festival','A new room is built in a garden'],answer:0,evidence:'He returns the broom before going home and closes the door carefully.',explanation:'The passage describes responsible use of the shared tool room.'},inference:{question:'What can readers infer about the tool room?',options:['People are expected to care for its tools','It is always locked during the day','It contains only flowers','It belongs to Fajar’s family'],answer:0,evidence:'He returns the broom before going home and closes the door carefully.',explanation:'Returning the tool and closing the room suggest shared responsibility.'},vocabOptions:['take or bring something back','sweep a path','paint a door','open a window'],vocabAnswer:0},

  {id:'pack-l2-01',title:'The Solar Oven Club',level:2,category:'Science',passage:'The Solar Oven Club wants to warm bread without using electricity. The students build a box from cardboard and cover the inside with foil. They place the box in direct sunlight and record the temperature every ten minutes. Their first test is slow because a tree creates shade, so they move the box to a brighter place. The second test warms the bread more quickly.',word:'direct',indonesian:'langsung',meaning:'coming straight from a source without a barrier',detail:{question:'Why is the first test slow?',options:['A tree creates shade','The bread is frozen','The box is made of metal','The students forget to record data'],answer:0,evidence:'Their first test is slow because a tree creates shade.',explanation:'Shade reduces the sunlight reaching the box.'},main:{question:'What is the passage mainly about?',options:['Students improve a solar oven by testing and changing its position','Students cook bread in an electric oven','A tree grows beside a science room','A club measures the size of cardboard boxes'],answer:0,evidence:'The second test warms the bread more quickly.',explanation:'The passage follows a simple test, problem and improvement.'},inference:{question:'What does the second test suggest?',options:['More sunlight can make the oven work better','Foil prevents all heat from entering','Temperature records are unnecessary','The students should move the tree'],answer:0,evidence:'They move the box to a brighter place. The second test warms the bread more quickly.',explanation:'The change in light and result supports this conclusion.'},vocabOptions:['coming straight from a source without a barrier','very far from a source','made from recycled paper','written in a notebook'],vocabAnswer:0},
  {id:'pack-l2-02',title:'The Repair Café',level:2,category:'Community',passage:'Once a month, volunteers open a Repair Café in the town hall. Visitors bring broken lamps, torn bags and noisy fans. A volunteer checks each object before deciding whether it is safe to repair. Some items need a new part, while others only need cleaning. The visitors learn how small repairs can extend the useful life of everyday objects.',word:'extend',indonesian:'memperpanjang',meaning:'make something last or continue for longer',detail:{question:'What does a volunteer do before deciding to repair an object?',options:['Checks whether it is safe','Sells it at the town hall','Throws it into a bin','Asks the visitor to buy a fan'],answer:0,evidence:'A volunteer checks each object before deciding whether it is safe to repair.',explanation:'Safety comes before the repair decision.'},main:{question:'What is the central message?',options:['Repairing suitable objects can reduce waste and extend their use','All broken objects should be repaired immediately','Visitors come to the town hall to buy lamps','Cleaning is more expensive than replacing parts'],answer:0,evidence:'The visitors learn how small repairs can extend the useful life of everyday objects.',explanation:'The final sentence states the lesson of the event.'},inference:{question:'Why might some objects not be repaired?',options:['A repair may be unsafe or require an unavailable part','Volunteers dislike lamps and bags','The town hall has no tables','Visitors are not allowed to ask questions'],answer:0,evidence:'A volunteer checks each object before deciding whether it is safe to repair. Some items need a new part.',explanation:'The safety check and need for parts limit what can be repaired.'},vocabOptions:['make something last or continue for longer','break something into pieces','carry something to a café','measure the noise of a fan'],vocabAnswer:0},
  {id:'pack-l2-03',title:'Mangrove Walk',level:2,category:'Environment',passage:'During a mangrove walk, a guide asks visitors to stay on the wooden path. The roots are easily damaged, and young fish use the shallow water between them as shelter. The group stops at three signs that explain how mangroves reduce erosion. At the end, the guide asks everyone to take their rubbish home. The walk is short, but it changes how the visitors see the muddy coastline.',word:'shelter',indonesian:'tempat berlindung',meaning:'a safe place that protects people or animals',detail:{question:'Why must visitors stay on the wooden path?',options:['The mangrove roots are easily damaged','The path leads to a restaurant','The water is too deep for fish','The guide wants visitors to walk faster'],answer:0,evidence:'The roots are easily damaged.',explanation:'Protecting the roots is the reason for staying on the path.'},main:{question:'What is the passage mainly about?',options:['A guided walk helps visitors understand and protect mangroves','A group builds a new wooden bridge','Visitors search for fish in deep water','A guide teaches people how to collect rubbish'],answer:0,evidence:'The walk is short, but it changes how the visitors see the muddy coastline.',explanation:'The walk builds understanding of the ecosystem and responsible behaviour.'},inference:{question:'What role do mangrove roots play in the passage?',options:['They provide habitat and help protect the coast','They make the wooden path slippery','They prevent all fish from entering the water','They are used to build the signs'],answer:0,evidence:'Young fish use the shallow water between them as shelter... mangroves reduce erosion.',explanation:'The passage gives both habitat and coastal-protection functions.'},vocabOptions:['a safe place that protects people or animals','a type of tree root','a sign beside a path','a wet piece of soil'],vocabAnswer:0},
  {id:'pack-l2-04',title:'The Missing Recipe',level:2,category:'Home',passage:'Mira wants to make her grandmother’s banana cake, but the recipe card is missing. She remembers three clues: the cake uses ripe bananas, the oven must be warm, and the mixture needs flour. She calls her grandmother to check the amount of sugar. After the call, Mira writes the recipe in a notebook and places the notebook beside the mixing bowl.',word:'ripe',indonesian:'matang',meaning:'ready to be eaten or used because it has developed fully',detail:{question:'What does Mira remember about the bananas?',options:['They must be ripe','They must be frozen','They must be green','They must be dried'],answer:0,evidence:'She remembers three clues: the cake uses ripe bananas...',explanation:'The first clue names the required bananas.'},main:{question:'What is the main focus of the passage?',options:['Mira reconstructs and records a family recipe','Mira buys a new oven for her grandmother','Mira learns how to grow banana trees','Mira loses a mixing bowl in the kitchen'],answer:0,evidence:'After the call, Mira writes the recipe in a notebook.',explanation:'Recovering and preserving the recipe is the central action.'},inference:{question:'Why does Mira call her grandmother?',options:['She needs to confirm a detail she does not remember','She wants to borrow an oven','She wants to ask about the bananas’ colour only','She has already finished the cake'],answer:0,evidence:'She calls her grandmother to check the amount of sugar.',explanation:'The call resolves missing recipe information.'},vocabOptions:['ready to be eaten or used because it has developed fully','hard and impossible to cut','covered with flour','too sweet to use'],vocabAnswer:0},
  {id:'pack-l2-05',title:'The Quiet Corner',level:2,category:'School',passage:'The school library creates a Quiet Corner for students who need a calm place to read. The corner has two lamps, a low shelf and a sign asking visitors to silence their phones. Students may use the space for twenty minutes before another reader takes a turn. The rule makes the corner available to more people, even during the busy lunch break.',word:'available',indonesian:'tersedia',meaning:'ready for someone to use or obtain',detail:{question:'How long may a student use the Quiet Corner?',options:['Twenty minutes','Two hours','The whole school day','Five seconds'],answer:0,evidence:'Students may use the space for twenty minutes before another reader takes a turn.',explanation:'The time limit is stated directly.'},main:{question:'Why does the library create the Quiet Corner?',options:['To give students a calm place to read','To store lamps during lunch','To teach students how to silence phones','To replace the whole library'],answer:0,evidence:'The school library creates a Quiet Corner for students who need a calm place to read.',explanation:'The first sentence states the purpose.'},inference:{question:'What is the likely benefit of the twenty-minute rule?',options:['More students can use the space','Students can leave their phones on loudly','The library can remove its shelves','Readers never need to take turns'],answer:0,evidence:'The rule makes the corner available to more people.',explanation:'The passage explicitly connects the rule with wider access.'},vocabOptions:['ready for someone to use or obtain','hidden from every reader','too noisy to enter','made of two lamps'],vocabAnswer:0},
  {id:'pack-l2-06',title:'A Bicycle Map',level:2,category:'Travel',passage:'The youth centre creates a map of safe bicycle routes. The team marks roads with heavy traffic in red and quieter streets in green. They also add a repair station near the market and a drinking-water point beside the park. Before printing the map, the students cycle each route to check whether the symbols match the real streets.',word:'route',indonesian:'rute atau jalur',meaning:'a way or direction between places',detail:{question:'What does the team mark in red?',options:['Roads with heavy traffic','Repair stations','Drinking-water points','Quieter streets'],answer:0,evidence:'The team marks roads with heavy traffic in red...',explanation:'Red identifies the busy roads.'},main:{question:'What is the purpose of the map?',options:['To help cyclists choose safer routes and useful stops','To show where students attend classes','To measure the traffic noise near a market','To advertise new bicycles'],answer:0,evidence:'The youth centre creates a map of safe bicycle routes.',explanation:'The route symbols and service points are designed for cyclists.'},inference:{question:'Why do students cycle each route before printing?',options:['They want to verify that the map reflects actual conditions','They need to race through every street','They want to remove the green symbols','They are looking for a new market'],answer:0,evidence:'They cycle each route to check whether the symbols match the real streets.',explanation:'The text states that the field check verifies the map.'},vocabOptions:['a way or direction between places','a place where bicycles are sold','a coloured map symbol','a traffic light'],vocabAnswer:0},
  {id:'pack-l2-07',title:'The Seed Exchange',level:2,category:'Nature',passage:'Neighbours bring vegetable seeds to a monthly seed exchange. Each envelope includes the plant name, the month it was collected and a short growing tip. People may take a different envelope if they leave one of their own. The organiser keeps a notebook so the group can see which plants grow well in the local soil.',word:'exchange',indonesian:'pertukaran',meaning:'give one thing and receive another in return',detail:{question:'What information is written on each envelope?',options:['The plant name, collection month and growing tip','The price of a bicycle and a bus route','The organiser’s home address only','A list of school subjects'],answer:0,evidence:'Each envelope includes the plant name, the month it was collected and a short growing tip.',explanation:'The three pieces of information are listed in the second sentence.'},main:{question:'What is the main idea?',options:['Neighbours share seeds and record what grows well','A shop sells expensive vegetables to visitors','People collect envelopes for a school project','A gardener refuses to share local seeds'],answer:0,evidence:'Neighbours bring vegetable seeds to a monthly seed exchange.',explanation:'Sharing and learning from local growing results define the exchange.'},inference:{question:'Why does the organiser keep a notebook?',options:['To compare plant results over time','To count how many envelopes are blue','To replace the seed envelopes','To write recipes for a market stall'],answer:0,evidence:'The organiser keeps a notebook so the group can see which plants grow well in the local soil.',explanation:'The purpose is stated in the final clause.'},vocabOptions:['give one thing and receive another in return','hide seeds under the soil','write a plant name','collect rainwater'],vocabAnswer:0},
  {id:'pack-l2-08',title:'Night Market Notice',level:2,category:'Community',passage:'A notice at the night market says that the west entrance will close at 8 p.m. because workers will repair a light. Visitors can still enter through the east gate. Stall owners are asked to keep the walkway clear while the repair takes place. The notice also reminds visitors to bring small cash because one payment machine will be offline.',word:'offline',indonesian:'tidak tersambung atau tidak berfungsi',meaning:'not connected to a working network or service',detail:{question:'Why will the west entrance close?',options:['Workers will repair a light','The market has no visitors','The east gate is too small','Stall owners are moving away'],answer:0,evidence:'The west entrance will close at 8 p.m. because workers will repair a light.',explanation:'The notice gives the repair as the reason.'},main:{question:'What is the notice mainly intended to do?',options:['Give visitors and stall owners practical instructions','Advertise a new payment machine','Explain how to repair a market light','Invite people to close the east gate'],answer:0,evidence:'The notice gives information about entrances, the walkway and payment.',explanation:'It prepares people for temporary changes at the market.'},inference:{question:'What should a visitor probably do after reading the notice?',options:['Use the east gate and carry some cash','Arrive at the west gate after 8 p.m.','Block the walkway during repairs','Bring only a credit card'],answer:0,evidence:'Visitors can still enter through the east gate... bring small cash.',explanation:'These are the two practical actions suggested by the notice.'},vocabOptions:['not connected to a working network or service','open all night','located beside the west entrance','paid with exact coins'],vocabAnswer:0},
  {id:'pack-l2-09',title:'The Community Radio Hour',level:2,category:'Media',passage:'Every Friday, a community radio station gives ten minutes to local teenagers. The teenagers report a school event, interview a shop owner or recommend a book. Before going live, the presenter checks names and asks guests to speak clearly. The short programme helps young people practise listening, asking questions and sharing information with their neighbours.',word:'recommend',indonesian:'merekomendasikan',meaning:'suggest something as a good choice',detail:{question:'What does the presenter check before the programme?',options:['Names and clear speaking','The price of every book','The colour of the radio room','The weather in another country'],answer:0,evidence:'Before going live, the presenter checks names and asks guests to speak clearly.',explanation:'Both checks appear in the third sentence.'},main:{question:'What is the main purpose of the radio programme?',options:['To give teenagers practice communicating with the community','To sell radio equipment to teenagers','To replace all school events','To teach shop owners how to read'],answer:0,evidence:'The short programme helps young people practise listening, asking questions and sharing information.',explanation:'The final sentence explains the educational purpose.'},inference:{question:'Why does the presenter check names?',options:['Accurate names help the broadcast respect its guests','Names make the radio louder','The station wants to hide the guests','Teenagers cannot ask questions'],answer:0,evidence:'Before going live, the presenter checks names...',explanation:'Checking names supports accurate and respectful reporting.'},vocabOptions:['suggest something as a good choice','speak into a microphone loudly','close a radio station','write a person’s name'],vocabAnswer:0},

  {id:'pack-l3-01',title:'Why Bees Matter',level:3,category:'Science',passage:'When bees visit flowers, pollen sticks to their bodies and moves from one flower to another. This movement helps many plants produce fruit and seeds. A school garden therefore plants several flowering species instead of one crop. The garden offers food for bees across more weeks, while students observe how pollinators support the wider food system.',word:'pollinator',indonesian:'hewan penyerbuk',meaning:'an animal that carries pollen between flowers',detail:{question:'How does pollen move between flowers?',options:['It sticks to bees and is carried to another flower','Students paint it onto every leaf','Rain changes it into seeds immediately','Roots carry it through the air'],answer:0,evidence:'Pollen sticks to their bodies and moves from one flower to another.',explanation:'The passage explains the movement through bees.'},main:{question:'What is the main idea of the passage?',options:['Pollinators help plants reproduce, so diverse gardens can support them','Bees eat every crop in a school garden','Students should grow only one flowering species','Fruit can grow without flowers or pollen'],answer:0,evidence:'This movement helps many plants produce fruit and seeds... the garden offers food for bees.',explanation:'The passage links bee activity, plant reproduction and garden design.'},inference:{question:'Why might several flowering species help the garden?',options:['They can provide food for bees over a longer period','They stop all insects from visiting','They make the soil disappear','They produce no fruit or seeds'],answer:0,evidence:'The garden offers food for bees across more weeks.',explanation:'Different flowering times extend the available food supply.'},vocabOptions:['an animal that carries pollen between flowers','a plant that grows without soil','a seed stored in a box','a person who sells flowers'],vocabAnswer:0},
  {id:'pack-l3-02',title:'The Floating Classroom',level:3,category:'Education',passage:'In a riverside district, a small boat carries books and science equipment to villages that are difficult to reach by road. The teacher does not simply deliver supplies. She reads with children, demonstrates water testing and leaves a set of activities for the next visit. Because the river level changes, the schedule remains flexible. The programme combines access to materials with regular contact between teacher and learners.',word:'flexible',indonesian:'fleksibel',meaning:'able to change or adapt when circumstances change',detail:{question:'Why does the schedule remain flexible?',options:['The river level changes','The boat has no books','The villages are beside a highway','The teacher only teaches science'],answer:0,evidence:'Because the river level changes, the schedule remains flexible.',explanation:'Changing river conditions can affect travel.'},main:{question:'What makes the floating classroom more than a delivery service?',options:['The teacher works directly with learners during each visit','The boat carries only boxes of equipment','The schedule never changes','The children study without books'],answer:0,evidence:'The teacher reads with children, demonstrates water testing and leaves activities.',explanation:'Direct teaching and follow-up activities make the programme educational.'},inference:{question:'What problem is the programme designed to address?',options:['Limited access to learning materials and teachers','A shortage of river water for boats','Too many science laboratories in villages','A need to replace all road transport'],answer:0,evidence:'The boat carries books and science equipment to villages that are difficult to reach by road.',explanation:'The first sentence identifies the access problem.'},vocabOptions:['able to change or adapt when circumstances change','moving only in a straight line','full of water','unwilling to teach children'],vocabAnswer:0},
  {id:'pack-l3-03',title:'A Better Bus Stop',level:3,category:'Design',passage:'A neighbourhood survey finds that commuters avoid one bus stop after dark. The stop has a working timetable, but its lamp does not reach the bench and the sign is hard to read from the road. The transport team adds a brighter lamp, paints a high-contrast border around the sign and moves the bench closer to the light. The changes are small, yet they respond to the specific barriers named by commuters.',word:'barrier',indonesian:'hambatan',meaning:'something that makes an action or goal more difficult',detail:{question:'What problem do commuters report?',options:['They avoid the stop after dark','The buses never have timetables','The bench is inside a shop','The sign is too bright'],answer:0,evidence:'A neighbourhood survey finds that commuters avoid one bus stop after dark.',explanation:'The survey identifies avoidance after dark.'},main:{question:'What is the passage mainly showing?',options:['Small design changes can respond to specific user problems','Bus stops should remove all benches','A survey cannot identify transport problems','High-contrast signs make buses travel faster'],answer:0,evidence:'The changes are small, yet they respond to the specific barriers named by commuters.',explanation:'The conclusion states the relationship between the feedback and design changes.'},inference:{question:'Why is the timetable not enough to solve the problem?',options:['People still struggle to see and use the stop safely at night','Commuters do not need transport information','The buses arrive only in the morning','The sign is already too large'],answer:0,evidence:'The stop has a working timetable, but its lamp does not reach the bench and the sign is hard to read.',explanation:'The passage contrasts information with practical visibility.'},vocabOptions:['something that makes an action or goal more difficult','a sign that shows a bus route','a light that shines from a bench','a person who drives a bus'],vocabAnswer:0},
  {id:'pack-l3-04',title:'The Language of Street Signs',level:3,category:'Language',passage:'A town replaces several confusing street signs with versions that use the same symbols, colours and arrow shapes. Designers test the signs with residents who have different ages and levels of literacy. One symbol looks clear to the designers but is misunderstood by many residents, so the team changes it before installation. The process shows why public information must be tested with the people who will use it.',word:'misunderstand',indonesian:'salah memahami',meaning:'understand something in an incorrect way',detail:{question:'Why does the team change one symbol?',options:['Many residents misunderstand it','The designers want more colours','The town has no street names','The arrows are made of metal'],answer:0,evidence:'One symbol... is misunderstood by many residents, so the team changes it.',explanation:'User testing reveals the problem.'},main:{question:'What is the main lesson?',options:['Public signs should be tested with their intended users','Designers should use as many symbols as possible','Street signs only need to look attractive','Residents should not comment on public information'],answer:0,evidence:'Public information must be tested with the people who will use it.',explanation:'The final sentence states the lesson.'},inference:{question:'Why include residents with different ages and literacy levels?',options:['A sign should communicate clearly to a diverse public','Only older residents can read symbols','Designers need help choosing street colours for homes','The town wants to remove all arrows'],answer:0,evidence:'Designers test the signs with residents who have different ages and levels of literacy.',explanation:'The diverse test group represents the people who need the signs.'},vocabOptions:['understand something in an incorrect way','write a street name carefully','change a sign’s colour','walk across a road'],vocabAnswer:0},
  {id:'pack-l3-05',title:'The Smallest Useful Change',level:3,category:'Work',passage:'A clinic asks patients why appointment forms take so long to complete. The answers reveal that people repeatedly write the same phone number on three different pages. The clinic redesigns the form so the number is entered once and copied into the other sections. Staff members still check the information, but patients finish sooner. The improvement does not require expensive software; it removes an unnecessary repetition from an existing process.',word:'repetition',indonesian:'pengulangan',meaning:'the act of doing or saying something again',detail:{question:'What causes patients to spend extra time?',options:['They write the same phone number three times','They wait for expensive software','They use a form with no pages','They visit three different clinics'],answer:0,evidence:'People repeatedly write the same phone number on three different pages.',explanation:'The repeated entry creates extra work.'},main:{question:'What is the central idea?',options:['Removing a small repeated task can improve an existing process','Clinics should stop checking patient information','New software is always needed for improvement','Long forms are useful because they repeat every detail'],answer:0,evidence:'It removes an unnecessary repetition from an existing process.',explanation:'The redesign improves the process through a simple change.'},inference:{question:'Why do staff still check the information?',options:['The change saves time but does not remove the need for accuracy','Staff want patients to rewrite the number','The new form cannot copy any information','The clinic has stopped using appointment forms'],answer:0,evidence:'Staff members still check the information, but patients finish sooner.',explanation:'The text distinguishes efficiency from quality control.'},vocabOptions:['the act of doing or saying something again','a medical appointment','a software programme','a phone number written once'],vocabAnswer:0},
  {id:'pack-l3-06',title:'A Community Radio Debate',level:3,category:'Media',passage:'A community radio programme invites two residents to discuss a proposed market rule. The host asks each speaker to explain a claim and provide an example. Listeners then send questions, including one that challenges an assumption shared by both speakers. In the final minutes, the host summarises points of agreement and disagreement without declaring a winner. The format treats public discussion as a way to examine reasons, not just announce opinions.',word:'assumption',indonesian:'anggapan',meaning:'an idea accepted as true without complete proof',detail:{question:'What does the host ask speakers to provide?',options:['A claim and an example','A market licence and a fee','A song and a weather report','A winner and a prize'],answer:0,evidence:'The host asks each speaker to explain a claim and provide an example.',explanation:'The two requested elements are stated directly.'},main:{question:'What is the programme’s approach to public discussion?',options:['It examines reasons and recognises agreement and disagreement','It chooses a winner before the discussion begins','It prevents listeners from asking questions','It treats every opinion as a proven fact'],answer:0,evidence:'The format treats public discussion as a way to examine reasons, not just announce opinions.',explanation:'The final sentence explains the programme’s approach.'},inference:{question:'Why is the listener’s challenging question important?',options:['It tests an idea that both speakers had accepted without checking','It ends the programme before anyone speaks','It proves that one resident is correct','It changes the market rule immediately'],answer:0,evidence:'A listener sends a question... that challenges an assumption shared by both speakers.',explanation:'Challenging a shared assumption adds critical examination.'},vocabOptions:['an idea accepted as true without complete proof','a rule printed at a market','a question asked by a host','a complete research report'],vocabAnswer:0},
  {id:'pack-l3-07',title:'A River in Numbers',level:3,category:'Environment',passage:'For six months, students measure the clarity of a river at the same point each Friday. After heavy rain, the water becomes less clear, but it returns closer to its earlier condition after several dry days. The students do not claim that one measurement explains the whole river. Instead, they compare dates, describe the limits of their method and suggest that more points should be tested.',word:'clarity',indonesian:'kejernihan',meaning:'the quality of being easy to see through or understand',detail:{question:'When does the water become less clear?',options:['After heavy rain','After several dry days','Before students begin measuring','Only at the same time every day'],answer:0,evidence:'After heavy rain, the water becomes less clear...',explanation:'The passage directly connects heavy rain with lower clarity.'},main:{question:'What does the students’ method show?',options:['Repeated measurements and stated limits make observations more careful','One measurement is enough to describe an entire river','Students should ignore changes after rain','A river can be understood without dates or comparisons'],answer:0,evidence:'They compare dates, describe the limits of their method and suggest that more points should be tested.',explanation:'The final sentence describes careful observation and limits.'},inference:{question:'Why suggest testing more points?',options:['Conditions may differ along the river','The students want to stop recording dates','The water is always equally clear','Heavy rain only affects school buildings'],answer:0,evidence:'The students do not claim that one measurement explains the whole river... more points should be tested.',explanation:'More points would show whether the observed pattern occurs elsewhere.'},vocabOptions:['the quality of being easy to see through or understand','the depth of a river','a date in a notebook','a kind of heavy rain'],vocabAnswer:0},
  {id:'pack-l3-08',title:'Reading a Museum Label',level:3,category:'History',passage:'A museum label beside an old fishing net states who made it, which fibres were used and how it was used. It does not say that the net belonged to one famous person. A visitor initially assumes that an object without a famous owner has little historical value. The guide points out that the label records work, materials and local knowledge. The visitor leaves understanding that history can be documented through ordinary objects.',word:'document',indonesian:'mendokumentasikan',meaning:'record information in a lasting form',detail:{question:'What information does the label include?',options:['The maker, fibres and use of the net','The price of a famous painting','The visitor’s personal opinion','The weather on the day of the visit'],answer:0,evidence:'The label... states who made it, which fibres were used and how it was used.',explanation:'The label records three kinds of information.'},main:{question:'What is the main point of the passage?',options:['Ordinary objects can provide evidence about history and local knowledge','Only objects owned by famous people belong in museums','Fishing nets have no historical value','Museum labels should contain personal opinions'],answer:0,evidence:'History can be documented through ordinary objects.',explanation:'The guide changes the visitor’s view of historical evidence.'},inference:{question:'What changes the visitor’s opinion?',options:['The guide explains what the object reveals about work and local knowledge','The museum gives the visitor a famous painting','The net is shown to be made of gold','The label removes all information about the net'],answer:0,evidence:'The guide points out that the label records work, materials and local knowledge.',explanation:'That explanation supplies a broader way to value the object.'},vocabOptions:['record information in a lasting form','repair a fishing net','visit a museum','own a famous object'],vocabAnswer:0},
  {id:'pack-l3-09',title:'The Feedback Loop',level:3,category:'Technology',passage:'A student team designs a reading app for older adults. Their first version uses small grey text because the screen looks uncluttered. During testing, several users say the text is difficult to read. The team increases the text size, improves contrast and tests the new version with the same users. The second round does not prove the app is perfect, but it gives the designers clearer evidence for the next revision.',word:'contrast',indonesian:'kontras',meaning:'a clear difference between colours, tones or ideas',detail:{question:'What problem do users report?',options:['The text is difficult to read','The app has too many audio files','The screen is too colourful','The team cannot test the app'],answer:0,evidence:'Several users say the text is difficult to read.',explanation:'The user feedback identifies the problem.'},main:{question:'What is the passage mainly about?',options:['User feedback guides repeated improvement of a design','A grey screen is always easier to read','Designers can finish an app without testing','Older adults do not use reading apps'],answer:0,evidence:'The second round... gives the designers clearer evidence for the next revision.',explanation:'The team uses testing to refine the app.'},inference:{question:'Why test the new version with the same users?',options:['Their experience can show whether the changes address the original problem','They are required to approve every app in the country','They need to make the text grey again','They cannot compare two versions'],answer:0,evidence:'The team... tests the new version with the same users.',explanation:'The same group helps the team compare feedback after changes.'},vocabOptions:['a clear difference between colours, tones or ideas','a list of app users','a small grey letter','a complete software failure'],vocabAnswer:0},

  {id:'pack-l4-01',title:'When a Town Shares Data',level:4,category:'Civics',passage:'A town publishes weekly data about waste collection, including missed streets, collection times and the number of reported problems. The dashboard does not solve the service by itself. Residents use it to compare patterns, while managers use the same information to adjust routes and check whether changes work. Because the town explains how the figures are collected, users can question the data without treating every number as a complete description of reality.',word:'transparent',indonesian:'transparan atau terbuka',meaning:'open and clear about information or decisions',detail:{question:'How do managers use the waste data?',options:['They adjust routes and check whether changes work','They hide missed streets from residents','They replace every collection vehicle','They publish only collection times'],answer:0,evidence:'Managers use the same information to adjust routes and check whether changes work.',explanation:'The passage names both uses.'},main:{question:'What is the passage mainly arguing?',options:['Shared data is useful when people understand its limits and collection method','A dashboard can solve a service without human decisions','Every number gives a complete picture of a town','Residents should not question public data'],answer:0,evidence:'Users can question the data without treating every number as a complete description of reality.',explanation:'The final sentence balances usefulness with limitations.'},inference:{question:'Why explain how the figures are collected?',options:['Users need context to interpret and evaluate the numbers','The town wants to make the dashboard colourful','Managers want to stop changing routes','Collection times are not related to waste service'],answer:0,evidence:'Because the town explains how the figures are collected...',explanation:'Collection methods affect what the numbers can show.'},vocabOptions:['open and clear about information or decisions','hidden from the public','made only of glass','fixed without any data'],vocabAnswer:0},
  {id:'pack-l4-02',title:'The Attention Budget',level:4,category:'Learning',passage:'A teacher asks students to read a complex article in two passes. During the first pass, they identify the topic, structure and unfamiliar terms without trying to memorise every sentence. During the second pass, they reread the sections that answer a specific question and annotate the evidence. The method treats attention as limited: careful rereading is reserved for the parts that matter most to the reading purpose.',word:'annotate',indonesian:'memberi anotasi atau catatan',meaning:'add brief notes or marks to a text',detail:{question:'What do students do during the first pass?',options:['Identify topic, structure and unfamiliar terms','Memorise every sentence','Write a full essay from memory','Skip the article completely'],answer:0,evidence:'During the first pass, they identify the topic, structure and unfamiliar terms...',explanation:'The first pass builds an overview.'},main:{question:'What principle guides the two-pass method?',options:['Use an overview first, then spend close attention on relevant evidence','Read every sentence once as quickly as possible','Avoid rereading difficult sections','Memorise terms before understanding the topic'],answer:0,evidence:'Careful rereading is reserved for the parts that matter most to the reading purpose.',explanation:'The final sentence states the principle.'},inference:{question:'Why might the first pass avoid memorising every sentence?',options:['Understanding the structure helps readers decide where close attention is useful','Students are not allowed to remember any detail','Complex articles contain no evidence','The teacher wants students to ignore unfamiliar terms'],answer:0,evidence:'They identify the topic, structure and unfamiliar terms without trying to memorise every sentence.',explanation:'The method prioritises strategic attention.'},vocabOptions:['add brief notes or marks to a text','read every sentence aloud','remove a paragraph from a text','translate a title into another language'],vocabAnswer:0},
  {id:'pack-l4-03',title:'A Forest Has Many Voices',level:4,category:'Environment',passage:'A forest monitoring project combines satellite images, ranger observations and recordings from local residents. Each source reveals a different part of the situation. Images show changes in land cover, rangers describe access and seasonal conditions, and residents report places that official routes rarely reach. The project team does not rank one source as automatically sufficient. It compares the sources and investigates disagreements before drawing a conclusion.',word:'corroborate',indonesian:'menguatkan dengan bukti lain',meaning:'confirm a claim by using additional evidence',detail:{question:'What can satellite images show?',options:['Changes in land cover','Local stories about every route','The exact thoughts of rangers','The sound of every animal'],answer:0,evidence:'Images show changes in land cover...',explanation:'The passage assigns land-cover change to the images.'},main:{question:'What is the project’s central method?',options:['Combine different sources and investigate disagreements','Use only satellite images because they are faster','Ignore local residents when official routes exist','Draw conclusions before comparing evidence'],answer:0,evidence:'It compares the sources and investigates disagreements before drawing a conclusion.',explanation:'The final sentence describes triangulation across sources.'},inference:{question:'Why are resident reports valuable in this project?',options:['They may describe places official routes rarely reach','They replace all observations by rangers','They make satellite images unnecessary','They provide no information about the forest'],answer:0,evidence:'Residents report places that official routes rarely reach.',explanation:'Their local access adds information not captured by other sources.'},vocabOptions:['confirm a claim by using additional evidence','remove a source from a project','draw a route on a satellite image','record a forest sound'],vocabAnswer:0},
  {id:'pack-l4-04',title:'The Case for Repair',level:4,category:'Economy',passage:'A repair policy can look slower than replacing an item, especially when the purchase price is the only cost considered. A fuller comparison includes transport, discarded materials, worker time, spare parts and the skills gained through maintenance. Repair is not always the best choice: a dangerous product or an unavailable part may justify replacement. The stronger argument is not that repair wins every time, but that decisions improve when the whole life of an item enters the calculation.',word:'justify',indonesian:'membenarkan atau memberi alasan',meaning:'show that an action or decision is reasonable',detail:{question:'What costs does a fuller comparison include?',options:['Transport, discarded materials, worker time, spare parts and skills','Only the purchase price','The colour of the item and its brand name','The weather during delivery'],answer:0,evidence:'A fuller comparison includes transport, discarded materials, worker time, spare parts and the skills gained through maintenance.',explanation:'The passage lists the broader costs and benefits.'},main:{question:'What is the author’s qualified position?',options:['Repair can be valuable, but the choice should consider the item’s whole life and safety','Repair is always better than replacement','Purchase price is the only useful evidence','Dangerous products should never be replaced'],answer:0,evidence:'The stronger argument is not that repair wins every time...',explanation:'The author supports repair as a considered option, not an absolute rule.'},inference:{question:'Why mention situations where replacement is justified?',options:['To show that the argument is conditional rather than absolute','To prove that spare parts are never useful','To suggest that maintenance has no skills value','To make the purchase price the only factor'],answer:0,evidence:'Repair is not always the best choice: a dangerous product or an unavailable part may justify replacement.',explanation:'The exception clarifies the limits of the position.'},vocabOptions:['show that an action or decision is reasonable','buy a product at a low price','throw away a broken object','calculate a worker’s salary'],vocabAnswer:0},
  {id:'pack-l4-05',title:'Two Maps, One Journey',level:4,category:'Travel',passage:'A traveller compares a printed hiking map with a digital map before leaving. The printed map shows contour lines clearly and remains usable when the phone battery is empty. The digital map displays recent trail closures and can estimate walking time. Neither map is complete: one may be outdated, while the other depends on signal and power. The traveller marks the route on both and carries a small battery pack, treating tools as sources of evidence rather than unquestionable authorities.',word:'outdated',indonesian:'sudah tidak mutakhir',meaning:'no longer current because newer information exists',detail:{question:'What does the printed map show clearly?',options:['Contour lines','Recent trail closures only','Phone battery level','Walking time based on signal'],answer:0,evidence:'The printed map shows contour lines clearly...',explanation:'Contour lines are the named strength of the printed map.'},main:{question:'What is the main lesson of the comparison?',options:['Different tools have different strengths and limits, so cross-checking is useful','Digital maps are always correct','Printed maps cannot help hikers','A traveller should carry no backup tools'],answer:0,evidence:'Treating tools as sources of evidence rather than unquestionable authorities.',explanation:'The passage recommends using both tools critically.'},inference:{question:'Why mark the route on both maps?',options:['The traveller wants a backup if one tool becomes unreliable','The two maps cannot show the same route','The phone battery is already empty','Contour lines are not useful for hiking'],answer:0,evidence:'The traveller marks the route on both and carries a small battery pack...',explanation:'Using both maps creates redundancy and supports safer planning.'},vocabOptions:['no longer current because newer information exists','easy to carry in a pocket','showing a steep hill','connected to a phone signal'],vocabAnswer:0},
  {id:'pack-l4-06',title:'The Unfinished Bridge',level:4,category:'Engineering',passage:'A bridge project stops after engineers discover that the riverbed is weaker than the original survey suggested. Some residents call the delay a failure, while the engineering team calls it a safety decision. The project manager publishes the test results, the revised design and the new uncertainty about cost. Construction has not resumed, but the public record makes clear which assumption changed and why the original schedule is no longer reliable.',word:'assumption',indonesian:'asumsi atau anggapan',meaning:'a belief accepted as true for planning or reasoning',detail:{question:'Why does construction stop?',options:['The riverbed is weaker than expected','Residents refuse to cross the bridge','The original survey is unavailable','The bridge is already complete'],answer:0,evidence:'Engineers discover that the riverbed is weaker than the original survey suggested.',explanation:'The new site evidence changes the safety assessment.'},main:{question:'What is the passage mainly about?',options:['Transparent reporting can explain why a safety-related project changes course','All construction delays are caused by public criticism','A bridge should be built according to its first schedule','Testing is less important than finishing quickly'],answer:0,evidence:'The public record makes clear which assumption changed and why the original schedule is no longer reliable.',explanation:'The reporting explains the decision and its basis.'},inference:{question:'Why publish the revised design and uncertainty about cost?',options:['The public needs to understand the consequences of the changed evidence','The manager wants to hide the riverbed problem','The bridge has no engineering design','The project is certain to cost less'],answer:0,evidence:'The project manager publishes the test results, the revised design and the new uncertainty about cost.',explanation:'Publishing the information supports informed public understanding.'},vocabOptions:['a belief accepted as true for planning or reasoning','a completed bridge inspection','a material used in a riverbed','a public celebration'],vocabAnswer:0},
  {id:'pack-l4-07',title:'Designing for Everyone',level:4,category:'Accessibility',passage:'A museum redesigns an exhibition after observing how visitors move through it. The team adds captions to video, a tactile diagram beside the large map and a bench near the longest text panel. These changes do not create a separate exhibition for a small group. They add different ways to access the same ideas. The evaluation therefore asks not only whether visitors like the design, but also whether more visitors can understand and use it independently.',word:'access',indonesian:'akses atau kesempatan menggunakan',meaning:'the ability or opportunity to reach, use or understand something',detail:{question:'What is placed beside the large map?',options:['A tactile diagram','A video camera','A ticket desk','A long staircase'],answer:0,evidence:'The team adds captions to video, a tactile diagram beside the large map...',explanation:'The tactile diagram is named directly.'},main:{question:'What design principle does the passage support?',options:['Offer multiple ways to access shared ideas','Create a separate exhibition for every visitor','Measure only whether visitors like the colours','Remove text from all museum displays'],answer:0,evidence:'They add different ways to access the same ideas.',explanation:'The passage presents inclusive access as a shared design goal.'},inference:{question:'Why include independent understanding in the evaluation?',options:['A design can be attractive yet still difficult to use without help','Visitors should never talk to museum staff','Likes are impossible to measure','A bench makes every text shorter'],answer:0,evidence:'The evaluation... asks... whether more visitors can understand and use it independently.',explanation:'The evaluation tests practical access, not only preference.'},vocabOptions:['the ability or opportunity to reach, use or understand something','a museum object made of stone','a printed ticket','a way to measure visitor height'],vocabAnswer:0},
  {id:'pack-l4-08',title:'The Cost of Convenience',level:4,category:'Technology',passage:'A school considers an app that automatically sends reminders to families. The app could reduce missed deadlines, but it would also collect contact details and create messages that some families might receive at inconvenient times. The school compares the benefit with privacy, language access and the risk of making families feel watched. It decides to pilot the app with clear consent, an opt-out route and a non-digital reminder. Convenience becomes one design goal among several, not the only measure of success.',word:'consent',indonesian:'persetujuan',meaning:'permission given after a person understands what will happen',detail:{question:'What could the app reduce?',options:['Missed deadlines','Contact details','Language access','All school communication'],answer:0,evidence:'The app could reduce missed deadlines...',explanation:'The potential benefit is stated at the beginning.'},main:{question:'Why does the school pilot the app with an opt-out route?',options:['To test usefulness while protecting choice and access','To force every family to use the app','To collect more contact details secretly','To remove non-digital communication'],answer:0,evidence:'It decides to pilot the app with clear consent, an opt-out route and a non-digital reminder.',explanation:'The safeguards protect choice and include families who need another route.'},inference:{question:'What does the final sentence suggest about convenience?',options:['Convenience should be balanced with privacy, access and trust','Convenience is always harmful to families','Privacy has no connection to school technology','Only digital reminders count as success'],answer:0,evidence:'Convenience becomes one design goal among several, not the only measure of success.',explanation:'The school adopts a multi-factor decision.'},vocabOptions:['permission given after a person understands what will happen','a reminder sent without permission','a school deadline','a language used in an app'],vocabAnswer:0},
  {id:'pack-l4-09',title:'A Question of Evidence',level:4,category:'Media Literacy',passage:'A headline claims that a new study proves a learning method works for every student. The article links to the study, but the study tested a small group in one age range and measured one short-term outcome. A careful reader does not discard the result; instead, the reader asks what the study actually supports and what remains uncertain. Strong reading can involve respect for evidence and restraint about claims that reach beyond it.',word:'restraint',indonesian:'pengendalian diri',meaning:'careful control that prevents an action from going too far',detail:{question:'What limits does the reader notice?',options:['A small group, one age range and one short-term outcome','No link to the study and no measured outcome','A study covering every student in every country','A headline with no words about learning'],answer:0,evidence:'The study tested a small group in one age range and measured one short-term outcome.',explanation:'These are the stated limits.'},main:{question:'What is the passage mainly teaching?',options:['Readers should match the strength of a claim to the evidence','Readers should reject every study with a small sample','A headline is always more accurate than a study','Evidence supports claims about every student automatically'],answer:0,evidence:'The reader asks what the study actually supports and what remains uncertain.',explanation:'The passage promotes careful interpretation rather than automatic acceptance or rejection.'},inference:{question:'Why does the reader not discard the study?',options:['A limited result can still provide useful evidence within its limits','The headline proves the study is universal','Short-term outcomes are never useful','The study contains no information at all'],answer:0,evidence:'A careful reader does not discard the result; instead, the reader asks what the study actually supports...',explanation:'The reader preserves useful information while limiting the claim.'},vocabOptions:['careful control that prevents an action from going too far','a headline printed in large letters','a study group of every student','a result with no limits'],vocabAnswer:0}
].map(makePackReading);

